function stem(word) {
  let w = word.toLowerCase().replace(/ё/g, 'е');
  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);
  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');
  return w.slice(0, 6);
}

function terms(text) {
  return (String(text).toLowerCase().match(/[\p{L}\p{N}]+/gu) || [])
    .filter((w) => w.length > 1 && !STOP.has(w))
    .map(stem)
    .filter((w) => w.length > 1);
}

function escapeHtml(text) {
  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function sheetRows(values) {
  const [head = [], ...rows] = values || [];
  const keys = head.map((h) => String(h).trim().toLowerCase());
  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));
}

const { input } = $('Config').first().json;
const categories = ['lead', 'support', 'billing', 'partner', 'spam', 'other'];
const category = categories.includes(String(input.category).toLowerCase()) ? String(input.category).toLowerCase() : 'other';
const priority = ['low', 'normal', 'high', 'urgent'].includes(String(input.priority).toLowerCase()) ? String(input.priority).toLowerCase() : 'normal';
const row = [
  new Date().toISOString(), input.customer_contact || '', input.email_subject || '', category, priority,
  String(input.summary || '').slice(0, 1000), category === 'spam' ? '' : String(input.draft_reply || '').slice(0, 4000),
  category === 'spam' ? 'spam' : 'draft', input.session_id || '',
];
const alert_html = priority === 'urgent' || priority === 'high' ? [
  `<b>📧 ${priority === 'urgent' ? 'Срочное' : 'Важное'} письмо · ${escapeHtml(category)}</b>`,
  `От: ${escapeHtml(input.customer_contact || '')}`,
  `Тема: ${escapeHtml(input.email_subject || '')}`,
  '',
  escapeHtml(input.summary || ''),
  '',
  'Черновик ответа — в листе Inbox.',
].join('\n') : '';
return [{ json: { category, priority, row, alert_html } }];

// Email Result: что агент разбора почты узнает о сохранённом письме.
const e = $('Email Row').first().json;
const saved = $('Append Email').first().json;
if (saved.error) {
  return [{ json: { ok: false, service_error: String(saved.error.message || saved.error).slice(0, 300), note: 'Разбор письма не сохранился. Сообщи об этом оркестратору.' } }];
}
return [{ json: { ok: true, category: e.category, priority: e.priority, alerted: Boolean(e.alert_html), note: 'Письмо разобрано, черновик ответа сохранён. Клиенту ничего не отправлено — ответ отправит человек.' } }];

