  '',
  `<b>Причина:</b> ${escapeHtml(input.reason || 'не указана')}`,
  `<b>Суть:</b> ${escapeHtml(input.summary || '')}`,
  input.last_message && `\n<blockquote>${escapeHtml(input.last_message)}</blockquote>`,
].filter(Boolean);
return [{ json: { alert_html: lines.join('\n') } }];

// Handoff Result: что модель узнает о передаче.
const { config } = $('Config').first().json;
const res = $input.first().json;
if (res.error || res.ok === false) {
  return [{ json: { ok: false, service_error: String(res.error?.message || res.error || res.description || 'telegram').slice(0, 300), note: 'Не удалось уведомить менеджера. Создай обращение (create_ticket) и назови клиенту его номер.' } }];
}
